import{decode as b64u}from"./base64url.js";import{decoder}from"../lib/buffer_utils.js";import{isObject}from"../lib/type_checks.js";import{JWTInvalid}from"./errors.js";export function decodeJwt(e){if("string"!=typeof e)throw new JWTInvalid("JWTs must use Compact JWS serialization, JWT must be a string");const{1:t,length:i}=e.split(".");if(5===i)throw new JWTInvalid("Only JWTs using Compact JWS serialization can be decoded");if(3!==i)throw new JWTInvalid("Invalid JWT");if(!t)throw new JWTInvalid("JWTs must contain a payload");let o,a;try{o=b64u(t)}catch{throw new JWTInvalid("Failed to base64url decode the payload")}try{a=JSON.parse(decoder.decode(o))}catch{throw new JWTInvalid("Failed to parse the decoded payload as JSON")}if(!isObject(a))throw new JWTInvalid("Invalid JWT Claims Set");return a}